import{_ as t,o as s,c as i,ao as a}from"./chunks/framework.DA_3JxoV.js";const c=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"contributing.md","filePath":"contributing.md","lastUpdated":null}'),n={name:"contributing.md"};function o(r,e,l,p,h,d){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="Contributing" tabindex="-1">Contributing <a class="header-anchor" href="#Contributing" aria-label="Permalink to &quot;Contributing {#Contributing}&quot;">​</a></h1><p>Contributions to MPSKit.jl are welcome, from bug reports and questions to documentation fixes and new algorithms. This page summarizes the practical workflow; the authoritative version is the <a href="https://github.com/QuantumKitHub/MPSKit.jl/blob/master/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a> file in the repository.</p><h2 id="Asking-questions-and-reporting-bugs" tabindex="-1">Asking questions and reporting bugs <a class="header-anchor" href="#Asking-questions-and-reporting-bugs" aria-label="Permalink to &quot;Asking questions and reporting bugs {#Asking-questions-and-reporting-bugs}&quot;">​</a></h2><p>Questions and bug reports both go through <a href="https://github.com/QuantumKitHub/MPSKit.jl/issues" target="_blank" rel="noreferrer">GitHub issues</a>, which provides two templates: a <strong>bug report</strong> for things that do not work as expected, and a <strong>question</strong> for anything else. General discussion is also welcome on <a href="https://github.com/QuantumKitHub/MPSKit.jl/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a>.</p><p>A good bug report includes a minimal working example (the smallest snippet that reproduces the problem), the full error message and stacktrace, and version information for MPSKit, TensorKit, and Julia:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" class="repl-prompt repl-prompt-julia">julia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;" class="repl-prompt repl-prompt-julia">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" class="repl-prompt repl-prompt-julia">julia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;" class="repl-prompt repl-prompt-julia">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MPSKit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;TensorKit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" class="repl-prompt repl-prompt-julia">julia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;" class="repl-prompt repl-prompt-julia">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> versioninfo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><h2 id="Development-setup" tabindex="-1">Development setup <a class="header-anchor" href="#Development-setup" aria-label="Permalink to &quot;Development setup {#Development-setup}&quot;">​</a></h2><p>Fork and clone the repository, then develop the package against your local checkout from the Julia REPL:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" class="repl-prompt repl-prompt-pkg">pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;" class="repl-prompt repl-prompt-pkg">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dev </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">path</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">to</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">your</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">clone</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MPSKit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">jl</span></span></code></pre></div><h2 id="Running-the-tests" tabindex="-1">Running the tests <a class="header-anchor" href="#Running-the-tests" aria-label="Permalink to &quot;Running the tests {#Running-the-tests}&quot;">​</a></h2><p>The repository root is a Julia workspace whose <code>Project.toml</code> lists <code>test</code>, <code>docs</code>, and <code>examples</code> as workspace projects. Run the full test suite from the repository root with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>julia --project=test test/runtests.jl</span></span></code></pre></div><p>The tests are organized by topic under <code>test/</code> (<code>algorithms/</code>, <code>states/</code>, <code>operators/</code>, <code>misc/</code>, <code>gpu/</code>). GPU tests only run when a functional CUDA/cuTENSOR install is detected, so most contributors exercise only the CPU tests. A <code>--fast</code> flag is available for a quicker, reduced run while iterating.</p><h2 id="Code-formatting" tabindex="-1">Code formatting <a class="header-anchor" href="#Code-formatting" aria-label="Permalink to &quot;Code formatting {#Code-formatting}&quot;">​</a></h2><p>The repository is formatted with <a href="https://github.com/fredrikekre/Runic.jl" target="_blank" rel="noreferrer">Runic</a>. Formatting is checked automatically on pull requests, and a <a href="https://pre-commit.com/" target="_blank" rel="noreferrer">pre-commit</a> hook (<code>.pre-commit-config.yaml</code>) runs Runic locally if you use pre-commit. Please format any Julia files you touch before opening a pull request.</p><h2 id="Building-the-documentation" tabindex="-1">Building the documentation <a class="header-anchor" href="#Building-the-documentation" aria-label="Permalink to &quot;Building the documentation {#Building-the-documentation}&quot;">​</a></h2><p>The documentation uses <a href="https://github.com/JuliaDocs/Documenter.jl" target="_blank" rel="noreferrer">Documenter.jl</a> with the <a href="https://github.com/LuxDL/DocumenterVitepress.jl" target="_blank" rel="noreferrer">DocumenterVitepress</a> backend, so a full site render needs Node.js (with <code>npm</code>) in addition to Julia. For routine verification of code examples, doctests run on the Documenter side and need no Node:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>julia --project=docs -e &#39;using Documenter, MPSKit; doctest(MPSKit)&#39;</span></span></code></pre></div><p>A full local site build is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>julia --project=docs docs/make.jl</span></span></code></pre></div><h2 id="Opening-a-pull-request" tabindex="-1">Opening a pull request <a class="header-anchor" href="#Opening-a-pull-request" aria-label="Permalink to &quot;Opening a pull request {#Opening-a-pull-request}&quot;">​</a></h2><p>Keep pull requests small and focused. Describe what the change does and why, link any related issues, and fill in the checklist in the PR template. If your change is user-facing (a new feature, behavior change, bug fix, deprecation, or removal), add an entry under the <code>[Unreleased]</code> section of the <a href="/MPSKit.jl/previews/PR449/changelog#Changelog">Changelog</a> in the category that matches your change.</p>`,22)])])}const g=t(n,[["render",o]]);export{c as __pageData,g as default};
